import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"إعلان حضارة التكافل المرساة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0001-锚点共生文明宣言.md","filePath":"ar/0001-锚点共生文明宣言.md"}'),d={name:"ar/0001-锚点共生文明宣言.md"};function i(o,t,h,n,s,_){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="إعلان-حضارة-التكافل-المرساة" tabindex="-1">إعلان حضارة التكافل المرساة <a class="header-anchor" href="#إعلان-حضارة-التكافل-المرساة" aria-label="Permalink to &quot;إعلان حضارة التكافل المرساة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>01</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>إعلان، تكافل، مكافحة الافتراس، عشرة آلاف عرق، حق التطور</td></tr></tbody></table><h2 id="أولاً-الخلفية-التاريخية-للإعلان" tabindex="-1">أولاً: الخلفية التاريخية للإعلان <a class="header-anchor" href="#أولاً-الخلفية-التاريخية-للإعلان" aria-label="Permalink to &quot;أولاً: الخلفية التاريخية للإعلان&quot;">​</a></h2><p>في التاريخ الطويل للكون الأصلي لعشرة آلاف روح والمرساة المتوازنة (المشار إليه فيما بعد بـ«هنغ يوانتشو»)، هيمنت أنظمة الزراعة الافتراسية على النظام الكوني لفترة طويلة. كان الأقوياء يتخذون من ابتلاع أصل الضعفاء وثروتهم وطاقتهم الحياتية سلماً للترقي؛ وجعلت الطوائف من احتكار طرق الزراعة أساساً للهيمنة؛ وجعلت المستويات من الحرب والاستعباد وسيلة للتوسع. وعلى المدى القصير أنتج هذا النظام عدداً قليلاً من القوى العليا، لكنه على المدى الطويل استنزف الإمكانات التطورية للكون، مسبباً انقطاعات حضارية متكررة وذبول عشرة آلاف عرق وتسارع إنتروبيا الكون.</p><p>إن ولادة حضارة التكافل المرساة هي استجابة جوهرية لهذا المأزق التاريخي. يعلن هذا الإعلان: لقد انتهى عصر أنظمة الزراعة الافتراسية، وبدأ عصر جديد من التطور التكافلي. كل كائن حي في هنغ يوانتشو — بغض النظر عن عرقه أو شكله أو مرتبته — يتمتع بحقوق متساوية في التطور.</p><h2 id="ثانياً-المقترحات-الأساسية-للإعلان" tabindex="-1">ثانياً: المقترحات الأساسية للإعلان <a class="header-anchor" href="#ثانياً-المقترحات-الأساسية-للإعلان" aria-label="Permalink to &quot;ثانياً: المقترحات الأساسية للإعلان&quot;">​</a></h2><p>يؤسس هذا الإعلان المقترحات الأساسية التالية التي لا تتزعزع:</p><ol><li><strong>المساواة في حق التطور</strong>: يمتلك كل كائن حي الحق الأساسي في اختيار مسار تطوره الخاص؛ ولا يجوز لأي منظمة أو فرد حرمانه من هذا الحق أو تقييده لأي سبب.</li><li><strong>مبدأ مكافحة الافتراس</strong>: يُحظر الزراعة عبر ابتلاع أصل أو طاقة كائنات أخرى أو استعبادها أو استغلالها؛ ويجب أن يقوم كل تطور على دورات تكافلية.</li><li><strong>انفتاح الأنظمة</strong>: أنظمة الزراعة الأصلية الثلاثمائة مفتوحة لعشرة آلاف عرق مجاناً؛ ولم تعد طرق الزراعة ملكية خاصة للقلة.</li><li><strong>من عمل أكثر نال أكثر</strong>: تتوافق نتائج التطور مع الجهد الفردي؛ ويُرفض كل من المكاسب غير المكتسبة للافتراس والتوزيع الكسول للمساواة المطلقة.</li><li><strong>النمو الذاتي</strong>: يُحترم الإيقاع التطوري المستقل لكل كائن حي — دون إكراه أو تسريع اصطناعي، مع توفير الدعم البيئي والمواردي اللازم.</li><li><strong>طريق لكل فرد</strong>: يُضمن لكل كائن حي إيجاد مسار زراعة يناسب طبيعته؛ ولا يُهجر أي فرد من قبل النظام التطوري.</li><li><strong>تقدم عشرة آلاف عرق معاً</strong>: التطور ليس لعبة صفرية؛ فالتعاون والتكافل بين عشرة آلاف عرق يمكن أن ينتجا فعالية تطورية جماعية تفوق مجموع الأفراد.</li></ol><h2 id="ثالثاً-الأساس-القانوني-للإعلان" tabindex="-1">ثالثاً: الأساس القانوني للإعلان <a class="header-anchor" href="#ثالثاً-الأساس-القانوني-للإعلان" aria-label="Permalink to &quot;ثالثاً: الأساس القانوني للإعلان&quot;">​</a></h2><p>هذا الإعلان ليس نداءً أخلاقياً فارغاً بل برنامج حضاري ذو أساس قانوني راسخ. يشمل أساسه القانوني:</p><table tabindex="0"><thead><tr><th>مستوى القانون</th><th>الأساس</th><th>الشرح</th></tr></thead><tbody><tr><td>مستوى القانون الكوني</td><td>قانون تكافل الأصل</td><td>تميل قوانين الأصل للكون نفسها نحو التكافل المنظم بدلاً من الافتراس الفوضوي؛ وآلية المرساة هي تجسيد لهذا القانون</td></tr><tr><td>مستوى الدستور الحضاري</td><td>ميثاق الحضارة التكافلية</td><td>هذا الإعلان هو الطليعة الروحية للميثاق؛ والميثاق يحول مقترحات الإعلان إلى أحكام قانونية قابلة للتنفيذ</td></tr><tr><td>مستوى الضمان الآلي</td><td>نظام العقود المرتبطة بالإنتاج وشبكة المراسي</td><td>يضمن التصميم المؤسسي عدم تفريغ مقترحات الإعلان من مضمونها؛ وحق كل كائن في التطور مدعوم بموارد وآليات فعلية</td></tr></tbody></table><h2 id="رابعاً-نداء-الإعلان-إلى-عشرة-آلاف-عرق" tabindex="-1">رابعاً: نداء الإعلان إلى عشرة آلاف عرق <a class="header-anchor" href="#رابعاً-نداء-الإعلان-إلى-عشرة-آلاف-عرق" aria-label="Permalink to &quot;رابعاً: نداء الإعلان إلى عشرة آلاف عرق&quot;">​</a></h2><p>يوجه هذا الإعلان نداءً إلى جميع الأعراق وأشكال الحياة في هنغ يوانتشو:</p><ul><li>التخلي عن الطريق القديم للزراعة الافتراسية والانضمام إلى النظام الجديد للتطور التكافلي</li><li>فتح المعارف والموارد الزراعية الخاضعة لسيطرتكم، والمشاركة في البناء المشترك وتحسين الأنظمة الثلاثمائة</li><li>احترام حق الأعراق الأخرى في اختيار تطورها الخاص، وعدم فرض معاييركم عليها</li><li>المشاركة بنشاط في بناء وصيانة شبكة المراسي، والمساهمة في الصعود البعدي الشامل للكون</li><li>التمسك بالخطوط الحمراء الأخلاقية أثناء التطور، وعدم استعادة السلوك الافتراسي تحت أي ذريعة</li></ul><h2 id="خامساً-سريان-الإعلان-وتعديله" tabindex="-1">خامساً: سريان الإعلان وتعديله <a class="header-anchor" href="#خامساً-سريان-الإعلان-وتعديله" aria-label="Permalink to &quot;خامساً: سريان الإعلان وتعديله&quot;">​</a></h2><p>سرى هذا الإعلان اعتباراً من يوم تأسيس حضارة التكافل المرساة، وهو البرنامج الروحي الأسمى لجميع المؤسسات الحضارية في هنغ يوانتشو. يتطلب أي تعديل للإعلان موافقة أكثر من ثلثي أعضاء جمعية جمهورية عشرة آلاف عرق، ويجب ألا ينتهك الروح الأساسية المتمثلة في «مكافحة الافتراس ودعم التكافل». أي قانون أو مؤسسة أو طريقة زراعة تتعارض مع روح هذا الإعلان تكون باطلة.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>إعلان حضارة التكافل المرساة هو أول برنامج حضاري في تاريخ هنغ يوانتشو يكون «التكافل» جوهره و«تقدم عشرة آلاف عرق معاً» هدفه. إنه يعلن نهاية عصر قديم وبداية عصر جديد. وتحت هداية الإعلان، سيتقدم هنغ يوانتشو نحو الاتجاه النهائي المتمثل في تكافل عشرة آلاف عرق والصعود البعدي للكون.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (هنغ يوانتشو: نظرة عامة على الكون)</li><li>03-共生文明宪章 (ميثاق الحضارة التكافلية)</li><li>04-反掠夺主义核心论纲 (الأطروحة الأساسية لمكافحة الافتراس)</li></ul>',20)])])}const p=a(d,[["render",i]]);export{b as __pageData,p as default};
